//! The Zipf port against wordfreq, and the cBpack reader's refusals.

use std::path::Path;

use serde_json::Value;

use super::*;
use crate::Language;
use crate::language::english;

/// The committed C4 fixture, generated by the bench's
/// `fixtures/c4_invented.py` from invented inputs.
pub(crate) fn fixture() -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/c4_invented.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("fixture is JSON")
}

/// Every word in the fixture gets wordfreq's Zipf value, exactly: the port
/// rounds as Python does, so the floats are the same.
#[test]
fn every_fixture_word_has_wordfreqs_zipf() {
    let fixture = fixture();
    let words = fixture["zipf"].as_array().expect("a zipf list");
    let wrong: Vec<String> = words
        .iter()
        .filter_map(|w| {
            let word = w["word"].as_str().expect("a word");
            let want = w["zipf"].as_f64().expect("a zipf");
            let got = english().zipf(word).value();
            // Bit for bit: the port rounds as Python does.
            (got.to_bits() != want.to_bits())
                .then(|| format!("{word:?}: got {got}, wordfreq {want}"))
        })
        .collect();
    assert!(words.len() > 1_000, "the fixture has {} words", words.len());
    assert_eq!(wrong, Vec::<String>::new());
}

/// The built-in list is wordfreq's whole English list: every word, in 800
/// centibel lists.
#[test]
fn the_built_in_list_has_every_english_word() {
    let list = WordList::english().unwrap();
    assert_eq!(list.buckets.len(), 321_180);
    assert_eq!(list.buckets.values().max(), Some(&799));
    // "the" is the commonest word: about once in 19 words, list 127.
    assert_eq!(list.buckets.get("the"), Some(&127));
}

/// msgpack for a cBpack whose lists are `lists`, with `header` as its first
/// element.
pub(crate) fn cbpack(header: &[u8], lists: &[&[&str]]) -> Vec<u8> {
    let mut out = Vec::new();
    let len = u16::try_from(lists.len() + 1).unwrap();
    out.push(0xdc);
    out.extend(len.to_be_bytes());
    out.extend(header);
    for list in lists {
        out.push(0x90 | u8::try_from(list.len()).unwrap());
        for word in *list {
            out.push(0xd9);
            out.push(u8::try_from(word.len()).unwrap());
            out.extend(word.as_bytes());
        }
    }
    out
}

/// wordfreq's header, `{"format": "cB", "version": 1}`.
pub(crate) const HEADER: &[u8] = b"\x82\xa6format\xa2cB\xa7version\x01";

/// A small cBpack reads back as its words and lists.
#[test]
fn a_cbpack_reads_as_its_words_and_lists() {
    let list = WordList::from_cbpack(&cbpack(HEADER, &[&[], &["red"], &["blue", "fish"]])).unwrap();
    let mut got: Vec<_> = list
        .buckets
        .iter()
        .map(|(w, &i)| (w.to_string(), i))
        .collect();
    got.sort();
    assert_eq!(
        got,
        [
            ("blue".to_owned(), 2),
            ("fish".to_owned(), 2),
            ("red".to_owned(), 1)
        ]
    );
}

/// A word listed twice keeps its later, rarer list, as wordfreq's dict does.
#[test]
fn a_word_listed_twice_keeps_its_rarer_list() {
    let list = WordList::from_cbpack(&cbpack(HEADER, &[&["red"], &["red"]])).unwrap();
    assert_eq!(list.buckets.get("red"), Some(&1));
}

/// The header's two entries may come in either order.
#[test]
fn the_headers_entries_may_come_in_either_order() {
    let swapped = b"\x82\xa7version\x01\xa6format\xa2cB";
    let list = WordList::from_cbpack(&cbpack(swapped, &[&["red"]])).unwrap();
    assert_eq!(list.buckets.get("red"), Some(&0));
}

/// Where a damaged cBpack says it went wrong.
fn malformed_at(bytes: &[u8]) -> (usize, &'static str) {
    match WordList::from_cbpack(bytes) {
        Err(WordListError::Malformed { at, what }) => (at, what),
        other => panic!("{other:?}"),
    }
}

/// Each way a cBpack can be damaged is refused, at the byte where it goes
/// wrong.
#[test]
fn a_damaged_cbpack_is_refused_where_it_goes_wrong() {
    const HEADER_WHAT: &str = "the header {format: cB, version: 1}";
    // No outer list, or an empty one.
    assert_eq!(malformed_at(b""), (0, "the outer list"));
    assert_eq!(malformed_at(b"\xa1x"), (0, "the outer list"));
    assert_eq!(malformed_at(b"\x90"), (1, "a header"));
    // A list that claims more elements than bytes are left.
    assert_eq!(
        malformed_at(b"\xdc\xff\xff"),
        (3, "an array no longer than the bytes left")
    );
    // A header that isn't a two-entry map, or has the wrong values or keys.
    assert_eq!(
        malformed_at(&cbpack(b"\x81\xa6format\xa2cB", &[])),
        (3, HEADER_WHAT)
    );
    let wrong_format = cbpack(b"\x82\xa6format\xa2cC\xa7version\x01", &[]);
    assert_eq!(malformed_at(&wrong_format), (23, HEADER_WHAT));
    let wrong_version = cbpack(b"\x82\xa6format\xa2cB\xa7version\x02", &[]);
    assert_eq!(malformed_at(&wrong_version), (23, HEADER_WHAT));
    let repeated = cbpack(b"\x82\xa6format\xa2cB\xa6format\xa2cB", &[]);
    assert_eq!(malformed_at(&repeated), (21, HEADER_WHAT));
    // A list of something other than words, a word that isn't UTF-8, and a
    // word that runs past the end.
    let mut not_words = cbpack(HEADER, &[]);
    not_words[2] = 2;
    not_words.extend(b"\x91\x01");
    assert_eq!(malformed_at(&not_words), (24, "a word"));
    let mut not_utf8 = cbpack(HEADER, &[]);
    not_utf8[2] = 2;
    not_utf8.extend(b"\x91\xa1\xff");
    assert_eq!(malformed_at(&not_utf8), (26, "a word in UTF-8"));
    let mut cut = cbpack(HEADER, &[&["red"]]);
    cut.pop();
    assert_eq!(malformed_at(&cut), (26, "a word"));
    // Bytes after the outer list.
    let mut trailing = cbpack(HEADER, &[&["red"]]);
    trailing.push(0x90);
    assert_eq!(malformed_at(&trailing), (29, "the end of the list"));
}

/// More than 1,000 frequency lists are refused, since a word in any of them
/// would be rarer than every lookup's floor.
#[test]
fn more_than_a_thousand_lists_are_refused() {
    let lists = vec![&[][..]; MAX_BUCKETS + 1];
    let (_, what) = malformed_at(&cbpack(HEADER, &lists));
    assert_eq!(what, "at most 1,000 frequency lists");
    let lists = vec![&[][..]; MAX_BUCKETS];
    assert!(WordList::from_cbpack(&cbpack(HEADER, &lists)).is_ok());
}

/// Bytes that aren't gzip are refused with the unpacker's error as the cause.
#[test]
fn bytes_that_arent_gzip_are_refused() {
    let err = WordList::from_gzip(b"not gzip").unwrap_err();
    assert!(matches!(err, WordListError::Unpack(_)), "{err:?}");
    assert!(err.source().is_some());
    assert_eq!(err.to_string(), "the word list couldn't be unpacked");
}

/// gzip that unpacks past the cap is refused, without unpacking it all.
#[test]
fn gzip_past_the_cap_is_refused() {
    use std::io::Write;
    let mut gz = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::fast());
    let zeros = vec![0u8; 1 << 20];
    for _ in 0..=MAX_UNPACKED >> 20 {
        gz.write_all(&zeros).unwrap();
    }
    let err = WordList::from_gzip(&gz.finish().unwrap()).unwrap_err();
    assert!(matches!(err, WordListError::TooLarge), "{err:?}");
}

/// The tokeniser splits as wordfreq does on the cases that differ from a
/// plain split on apostrophes and hyphens.
#[test]
fn tokens_split_as_wordfreq_splits_them() {
    let cases: [(&str, &[&str]); 9] = [
        ("Don't", &["don't"]),
        ("y'all", &["y", "all"]),
        ("ab'eh", &["ab", "eh"]),
        ("abc'eh", &["abc'eh"]),
        ("ab'1", &["ab", "1"]),
        ("1'2", &["1'2"]),
        ("specialists'", &["specialists"]),
        ("45-year-old", &["45", "year", "old"]),
        ("x''y", &["x", "y"]),
    ];
    for (text, want) in cases {
        assert_eq!(tokens(text), want, "{text:?}");
    }
}

/// Runs of two or more digits become zeros; a single digit stays.
#[test]
fn digit_runs_are_written_as_zeros() {
    assert_eq!(smash_numbers("2019"), "0000");
    assert_eq!(smash_numbers("b12c3"), "b00c3");
    assert_eq!(smash_numbers("a1b22c333"), "a1b00c000");
    assert_eq!(smash_numbers("5"), "5");
}

/// A run too long for a float has no frequency, where Python would raise
/// an overflow error: the word counts as unknown.
#[test]
fn a_digit_run_too_long_for_a_float_counts_as_unknown() {
    let long = "1".repeat(400);
    assert!(benford_freq(&long).abs() < 1e-300);
    assert!(english().zipf(&long).value().abs() < 1e-12);
}

/// Numbers get wordfreq's frequencies exactly: years on their curve (the
/// peak from 2019 to 2039, falling off either side, and a share for
/// four digits that aren't a year), other numbers by Benford's law, and
/// the product over a token's runs.
#[test]
fn numbers_get_wordfreqs_frequencies() {
    let cases: [(f64, f64); 9] = [
        (year_freq("2019"), 0.012_081_740_881_970_011),
        (year_freq("1999"), 0.008_261_898_369_213_96),
        (year_freq("2039"), 0.012_081_740_881_970_011),
        (year_freq("2040"), 0.007_629_521_390_057_183),
        (year_freq("2100"), 1.750_000_000_761_202_3e-5),
        (benford_freq("50"), 0.0078),
        (benford_freq("123"), 0.003),
        (benford_freq("007"), 8.999_999_999_999_999e-5),
        (digit_freq("a12b2019"), 0.000_362_452_226_459_100_3),
    ];
    for (i, (got, want)) in cases.into_iter().enumerate() {
        assert_eq!(
            got.to_bits(),
            want.to_bits(),
            "case {i}: {got} against {want}"
        );
    }
}

/// An apostrophe at the end of the text ends the token before it, with no
/// elision split off.
#[test]
fn a_final_apostrophe_ends_its_token() {
    assert_eq!(tokens("y'"), ["y"]);
    assert_eq!(tokens("ab'"), ["ab"]);
}
